```zig
pub fn encode(buffer: []u8, string: []const u8) []u8 {
    var buf_index: usize = 0;
    var i: usize = 0;
    while (i < string.len) {
        const c = string[i];
        var count: usize = 1;
        i += 1;
        while (i < string.len && string[i] == c) {
            count += 1;
            i += 1;
        }
        if (count > 1) {
            // Convert count to string
            var count_str: [10]u8 = undefined;
            var count_len: usize = 0;
            var n = count;
            if (n == 0) {
                count_str[count_len] = '0';
                count_len += 1;
            } else {
                while (n > 0) {
                    count_str[count_len] = @intCast('0' + (n % 10));
                    count_len += 1;
                    n /= 10;
                }
                // Reverse the digits
                var j: usize = 0;
                while (j < count_len / 2) {
                    const tmp = count_str[j];
                    count_str[j] = count_str[count_len - 1 - j];
                    count_str[count_len - 1 - j] = tmp;
                    j += 1;
                }
            }
            // Copy digits to buffer
            for (0..count_len) |k| {
                buffer[buf_index] = count_str[k];
                buf_index += 1;
            }
        }
        buffer[buf_index] = c;
        buf_index += 1;
    }
    return buffer[0..buf_index];
}

pub fn decode(buffer: []u8, string: []const u8) []u8 {
    var buf_index: usize = 0;
    var i: usize = 0;
    while (i < string.len) {
        var count: usize = 0;
        // Parse leading digits
        while (i < string.len && string[i] >= '0' && string[i] <= '9') {
            count = count * 10 + (string[i] - '0');
            i += 1;
        }
        if (i < string.len) {
            const c = string[i];
            i += 1;
            if (count == 0) {
                count = 1;
            }
            for (0..count) |_| {
                buffer[buf_index] = c;
                buf_index += 1;
            }
        }
    }
    return buffer[0..buf_index];
}
```

